import{useEffect,useState}from'react';import{Bell,Archive,Check}from'lucide-react';import{actOnNotification,getNotificationPreferences,listNotificationCentre,updateNotificationPreferences}from'../../lib/practiceOperationsApi';
export function ExternalNotificationCentre(){const[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[prefs,setPrefs]=useState({in_app:true,email:false,sms:false,whatsapp:false,digest_mode:'IMMEDIATE'});const load=async()=>{setState('loading');try{const[n,p]=await Promise.all([listNotificationCentre(),getNotificationPreferences()]);setItems(n.items||[]);setPrefs(p);setState((n.items||[]).length?'ready':'empty')}catch(e){setError(e.message);setState('error')}};useEffect(()=>{load()},[]);const act=async(id,a)=>{await actOnNotification(id,a);await load()};const save=async()=>{setPrefs(await updateNotificationPreferences(prefs))};return <section className="space-y-5"><header><h2 className="text-2xl font-bold">Notification Centre</h2><p className="text-sm text-slate-600">One view of authorised system events. Read and archive states change only when you act.</p></header><div className="rounded-2xl border bg-white p-4"><h3 className="font-bold">Preferences</h3><div className="mt-3 flex flex-wrap gap-4">{['email','sms','whatsapp'].map(k=><label key={k}><input type="checkbox" checked={Boolean(prefs[k])} onChange={e=>setPrefs({...prefs,[k]:e.target.checked})}/> {k.toUpperCase()}</label>)}<select aria-label="Digest frequency" value={prefs.digest_mode} onChange={e=>setPrefs({...prefs,digest_mode:e.target.value})}>{['IMMEDIATE','DAILY','WEEKLY'].map(x=><option key={x}>{x}</option>)}</select><button onClick={save} className="rounded-lg bg-slate-950 px-4 py-2 text-white">Save</button></div><p className="mt-2 text-xs text-slate-500">External delivery occurs only where a provider is configured. Mandatory operational and security notices remain in-app.</p></div>{state==='loading'?<p>Loading notifications…</p>:state==='error'?<p role="alert">Notifications unavailable: {error}</p>:state==='empty'?<p className="rounded-xl border border-dashed p-5">No notifications.</p>:<div className="space-y-2">{items.map(n=><article key={n.id} className="flex items-center gap-3 rounded-xl border bg-white p-4"><Bell size={18}/><div className="flex-1"><strong>{n.title}</strong><p className="text-xs">{n.category} · {n.state}</p></div>{n.state==='UNREAD'&&<button aria-label="Mark read" onClick={()=>act(n.id,'read')}><Check/></button>}<button aria-label="Archive" onClick={()=>act(n.id,'archive')}><Archive/></button></article>)}</div>}</section>}
